import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    m = int(input_data[1])
    MOD = 10**9 + 7

    def count_fib(k):
        if k == 1:
            return 2
        if k == 2:
            return 4
        a, b = 2, 4
        for _ in range(3, k + 1):
            a, b = b, (a + b) % MOD
        return b

    ans = (count_fib(n) * count_fib(m)) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
